Use bounded event waits that return a liveness result instead of throwing on timeout, then preserve the primary exception while attempting every cleanup:

```ts
async function waitForExit(child: ServiceProcess, timeoutMs: number): Promise<boolean> {
  if (child.exitCode !== null || child.signalCode !== null) return true;
  const signal = AbortSignal.timeout(timeoutMs);
  try {
    await once(child, "exit", { signal });
    return true;
  } catch (error) {
    if (signal.aborted) return false;
    throw error;
  }
}

async function runCleanup(
  scenarioFailed: boolean,
  tasks: readonly (() => Promise<void>)[],
): Promise<void> {
  const cleanupErrors: unknown[] = [];
  for (const task of tasks) {
    try {
      await task();
    } catch (error) {
      cleanupErrors.push(error);
    }
  }
  if (cleanupErrors.length === 0) return;
  if (scenarioFailed) {
    console.error("WP4 cleanup failures:", new AggregateError(cleanupErrors));
    return;
  }
  throw new AggregateError(cleanupErrors, "WP4 cleanup failed");
}
```

