    (response) => response.status,
    (error: unknown) => error,
  );

  if (shutdownStatus === 202 && (await waitForExit(service.child, 30_000))) return;

  await terminateProcessTree(service.child);

  if (
    shutdownStatus !== 202 &&
    !(shutdownStatus instanceof TypeError) &&
    !signal.aborted
  ) {
    throw new Error("projection fixture rejected graceful shutdown");
  }
}
